#!/usr/bin/env bash
# Generated by @navori/plugin-semgrep. Runs semgrep over TS/TSX files changed
# vs the configured base branch with the `p/default` ruleset. Skips silently if
# semgrep or git are absent — the tool is optional.
#
# NOTE: `p/default` (not `auto`) on purpose. `--config=auto` is INCOMPATIBLE
# with `--metrics=off` in semgrep >=1.x ("Cannot create auto config when metrics
# are off") because auto uploads project metadata to fetch tailored rules. A
# static ruleset keeps telemetry off AND runs deterministically — better for a
# gate anyway (same rules on every machine).
#
# Triggered as a PreToolUse(Bash) hook, gated to git commit / push / gh pr
# create — the security scan runs right before code lands or is pushed. Because
# the same content passes that gate up to three times per cycle, a green scan is
# memoized by content fingerprint (see the cache block below, #402).

set -euo pipefail

# Command extraction (payload → $cmd). Shared body, single source of truth.
# Shared hook boilerplate — inlined into each hook at render time (see the
# include directive in the source scripts + lib/hook-includes.ts). Single source
# of truth for the sibling gate scripts; DO NOT copy this body back into a hook
# by hand (that is the drift #225/#261 removed).
#
# PreToolUse(Bash) passes the tool input on stdin. Read one field out of it
# WITHOUT hard-depending on jq (NOT preinstalled on macOS): try jq, then node
# (Claude Code's own runtime), then a best-effort sed unwrap on the leaf key.
# Nothing extracted → empty output, and each caller decides what that means (the
# gate scripts scan defensively; guard-destructive waves the command through).
#
# $1 is a dotted path written HERE, never user input — the payload is the data.
# Generic on purpose: `.cwd` feeds the worktree resolver of #454 through the
# SAME hardened cascade instead of a second copy of it.
#
# $2 overrides the sed fallback's capture. `.*` (greedy, to the last quote on the
# line) is right for `command`, whose value can itself contain escaped quotes and
# which Claude Code sends LAST. Every other field takes the default `[^"]*` run,
# so a value with more JSON after it is not swallowed whole.
payload=$(cat)
payload_field() {
  if command -v jq >/dev/null 2>&1; then
    printf '%s' "$payload" | jq -r ".$1 // empty" 2>/dev/null && return 0
  fi
  if command -v node >/dev/null 2>&1; then
    printf '%s' "$payload" | node -e 'let s="";const p=process.argv[1].split(".");process.stdin.on("data",c=>s+=c).on("end",()=>{try{let v=JSON.parse(s);for(const k of p)v=v?.[k];process.stdout.write(String(v??""))}catch{}})' "$1" 2>/dev/null && return 0
  fi
  printf '%s' "$payload" | sed -n "s/.*\"${1##*.}\"[[:space:]]*:[[:space:]]*\"\(${2:-[^\"]*}\)\".*/\1/p"
}
extract_cmd() {
  payload_field tool_input.command '.*'
}
cmd=$(extract_cmd)

navori_audit_name="check-semgrep"
navori_audit_phase="PreToolUse"
navori_audit_tool="Bash"
# `source` names the PLUGIN, not core: disabling a plugin changes which hooks
# run, and without this the report cannot explain why a phase thinned out
# between two sessions.
navori_audit_source="plugin:semgrep"
# Fallback no-ops, overwritten by the real definitions the include brings in.
# They exist because this hook is FAIL-OPEN: if the file ever runs WITHOUT its
# includes expanded — a raw copy of the asset, a render that half-finished — an
# undefined function would be exit 127, and under `set -e` that KILLS the hook.
# A recorder that can kill the thing it observes is the one bug this partial may
# never have.
navori_audit_begin() { :; }
navori_audit_log() { :; }
# Shared audit-mode event recorder — inlined into each managed hook at render
# time (see the include directive in the source scripts + lib/hook-includes.ts).
#
# WHY (spec 0013): a hook is only visible to the transcript when it BLOCKS or
# INJECTS context. Every hook that runs and lets the action through is invisible,
# so `navori audit` could never answer "did the gate run, and what did it cost?".
# The transcript cannot be fixed — it is the host's format — so the harness
# records its own execution instead, and the session log becomes the source of
# truth for what the harness did.
#
# Expects `$payload` (the raw hook payload on stdin) to be in scope, and reads
# `$navori_audit_t0` for the start instant. Both are set by `navori_audit_begin`.
#
# Every variable read here carries a `:-` default ON PURPOSE: most managed hooks
# run under `set -euo pipefail`, where an unset variable ABORTS the hook. A
# recorder that can abort the thing it observes is worse than no recorder, so the
# partial must be safe to inline into `set -u` and `set +e` alike.
#
# FAIL-OPEN ABSOLUTE, and this matters more here than anywhere else: this code is
# inlined into hooks whose own contract is to never break a session. Observation
# must never become the reason an action fails, so every path returns 0 and
# nothing is ever written to stdout — a stray byte there would be interpreted by
# the host as hook output (context injection, or a block reason).

# Start the clock — but only after establishing that anything will be recorded.
#
# THE COST OF BEING OFF is the number that matters here: this code is inlined
# into hooks that fire on EVERY Bash call, and audit-mode is off for virtually
# every session of every user. An earlier version ran `perl` plus two `jq`
# invocations before it ever checked whether a log existed — three processes per
# hook, four hooks per command, ~48 ms on every single shell call for a feature
# nobody had turned on.
#
# So the gate is a pure-builtin one first: the per-repo audit directory only
# exists once audit-mode has been activated in this repo at least once. No
# subprocess, no parsing. Everything expensive lives behind it.
navori_audit_begin() {
  navori_audit_on=0

  navori_audit_root=${NAVORI_AUDITS_ROOT:-}
  if [ -z "$navori_audit_root" ]; then
    [ -n "${HOME:-}" ] || return 0
    navori_audit_root=$HOME/.navori/audits
  fi

  # The gate tests the audit ROOT, not the per-repo directory.
  #
  # Deriving the repo cheaply would mean `${CLAUDE_PROJECT_DIR##*/}` — and that
  # is WRONG: the authoritative repo comes from the payload's `cwd`, and the two
  # differ whenever a hook fires inside an agent worktree, since the hook process
  # starts in the main repo (#454). A gate built on the wrong name would silently
  # record nothing exactly where the harness runs its parallel work.
  #
  # The root alone is enough for what this gate is for: a user who has never
  # activated audit-mode anywhere has no `~/.navori/audits`, so the common case
  # costs one stat and zero processes. Someone who does use audit-mode pays the
  # parsing — which is the cost of the feature they turned on.
  [ -d "$navori_audit_root" ] || return 0

  navori_audit_on=1
  navori_audit_t0=$(navori_audit_now)
}

# Milliseconds since epoch, spending a process only when it has to.
#
# `$EPOCHREALTIME` is a BUILTIN in bash 5 and in zsh (with zsh/datetime, which
# the harness's zsh path already has): no fork at all. Only a shell without it
# pays for `perl`, and only a machine without perl degrades to whole seconds —
# `date` has no portable millisecond format (GNU has %s%3N, BSD does not).
navori_audit_now() {
  if [ -n "${EPOCHREALTIME:-}" ]; then
    # `1756... .123456` → milliseconds, with pure parameter expansion.
    navori_audit_epoch=${EPOCHREALTIME/,/.}
    printf '%s%s' "${navori_audit_epoch%%.*}" "$(printf '%.3s' "${navori_audit_epoch#*.}")"
    return 0
  fi
  perl -MTime::HiRes=time -e 'printf "%.0f", time*1000' 2>/dev/null \
    || printf '%s' $(( $(date +%s 2>/dev/null || echo 0) * 1000 ))
}

# navori_audit_log <verdict> [reason]
#
# `name`, `phase`, `tool` and `source` come from the caller's own variables,
# which the render sets per hook — the partial never guesses which hook it is
# inlined into.
navori_audit_log() {
  # The builtin-only gate from `navori_audit_begin`: when audit-mode was never
  # activated in this repo, nothing below runs and no process is spawned.
  [ "${navori_audit_on:-0}" = "1" ] || return 0
  # No payload, no jq, no clock → nothing to record. Each of these is a normal
  # state for a hook that bailed early, not an error worth surfacing.
  [ -n "${payload:-}" ] || return 0
  command -v jq >/dev/null 2>&1 || return 0

  # ONE jq for every field, not one per field: this runs on each hook of each
  # Bash call, and a fork is the most expensive thing in it. Newline-separated,
  # read back positionally.
  navori_audit_fields=$(printf '%s' "${payload:-}" | jq -r '[.session_id // "", .cwd // "", .agent_id // .subagent_id // ""] | .[]' 2>/dev/null) || return 0
  navori_audit_session=${navori_audit_fields%%
*}
  navori_audit_rest=${navori_audit_fields#*
}
  navori_audit_cwd=${navori_audit_rest%%
*}
  navori_audit_agent=${navori_audit_rest#*
}
  [ -n "$navori_audit_session" ] || return 0
  # Same character class the CLI enforces (#503): the id composes a path, so
  # anything path-shaped means the payload is not what we think it is.
  case "$navori_audit_session" in
    *[!A-Za-z0-9_-]*) return 0 ;;
  esac

  [ -n "$navori_audit_cwd" ] || navori_audit_cwd=$PWD
  navori_audit_repo=$(basename "$navori_audit_cwd" 2>/dev/null) || return 0
  [ -n "$navori_audit_repo" ] || return 0

  navori_audit_file=$navori_audit_root/$navori_audit_repo/session-$navori_audit_session.log

  # The session may not be the marked one even in a repo that has been audited
  # before. Also the writability check — a log that cannot be appended to is not
  # an error, it is simply not recording.
  [ -f "$navori_audit_file" ] || return 0
  [ -w "$navori_audit_file" ] || return 0

  # Volume valve, OFF by default.
  #
  # `PreToolUse(Bash)` chains four hooks, so every shell command leaves four
  # lines and most are `skip` — a long session runs to thousands. Set
  # NAVORI_AUDIT_SKIP_NOOPS=1 to drop the ones that did nothing.
  #
  # Default off on purpose: a `skip` is the ONLY evidence that a hook ran and
  # decided it had no business acting, which is exactly what distinguishes it
  # from a hook that never executed — the question that motivated recording
  # hooks at all. The valve trades that away knowingly; it must not be the
  # silent default.
  if [ "${NAVORI_AUDIT_SKIP_NOOPS:-0}" = "1" ]; then
    case "$1" in
      skip|noop) return 0 ;;
    esac
  fi

  navori_audit_end=$(navori_audit_now)
  navori_audit_ms=$(( navori_audit_end - ${navori_audit_t0:-$navori_audit_end} ))
  [ "$navori_audit_ms" -ge 0 ] 2>/dev/null || navori_audit_ms=0

  navori_audit_ts=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null) || navori_audit_ts=""
  # `navori_audit_agent` came out of the same single jq above. It is what lets
  # the report attribute a hook to a subagent WITHOUT guessing: with agents
  # running in parallel their time windows overlap, so attribution by timestamp
  # is the fallback, not the primary route.
  #
  # It is recorded, never trusted as an agent identity by itself (#560). What
  # `.agent_id` means depends on the PHASE: on the tool phases it is stable —
  # 485 events of one measured session carried 11 distinct ids, and the
  # subagents' resolved to real transcripts — but on `SubagentStop` the host
  # sends a fresh id per firing: 112 distinct ids for 117 firings, 102 of them
  # matching nothing under `~/.claude`. So a consumer that resolves this field
  # must treat "names nobody" as invalid data rather than as a different agent
  # (`ownerOf` in `lib/audit/parse.ts` is where that rule lives).

  printf '%s\n' "$(jq -cn \
    --arg ts "$navori_audit_ts" \
    --arg name "${navori_audit_name:-unknown}" \
    --arg phase "${navori_audit_phase:-unknown}" \
    --arg verdict "${1:-unknown}" \
    --arg reason "${2:-}" \
    --arg tool "${navori_audit_tool:-}" \
    --arg src "${navori_audit_source:-core}" \
    --arg agent "${navori_audit_agent:-}" \
    --argjson ms "$navori_audit_ms" \
    '{ts:$ts,event:"hook",name:$name,phase:$phase,verdict:$verdict,ms:$ms,source:$src}
     + (if $tool   == "" then {} else {tool:$tool}       end)
     + (if $reason == "" then {} else {reason:$reason}   end)
     + (if $agent  == "" then {} else {agentId:$agent}   end)' 2>/dev/null)" \
    >> "$navori_audit_file" 2>/dev/null

  return 0
}
navori_audit_begin

# Same shape as quality-gate-pre-commit: fires on every Bash call, works on
# almost none, so the verdict comes from the exit code rather than from a call
# per branch.
navori_audit_on_exit() {
  navori_audit_code=$?
  if [ "$navori_audit_code" -eq 0 ]; then
    navori_audit_log "allow" || true
  else
    navori_audit_log "block" "el escaneo de semgrep no paso" || true
  fi
  return 0
}
trap navori_audit_on_exit EXIT

# Gate to `git commit` / `git push` / `gh pr create`: the semgrep copy is the
# only gate that also fires on push and PR creation (remote-push security
# backstop). $TRIGGER_RE is consumed by the shared detector inlined below.
TRIGGER_RE='(^git([[:space:]]+-[a-zA-Z-]+(=[^[:space:]]+)?([[:space:]]+[^-][^[:space:]]*)?)*[[:space:]]+(commit|push)([[:space:]]|$))|(^gh[[:space:]]+pr[[:space:]]+create([[:space:]]|$))'
# Shared gate detector — inlined into each hook at render time (see the include
# directive in the source scripts + lib/hook-includes.ts). The caller MUST set
# $TRIGGER_RE (an ERE) before the include; it decides which git ops this hook
# gates. Single source of truth for the FIX B/C wrapper-peeling logic; DO NOT
# copy this body into a hook by hand.
#
# Detect whether $1 (a possibly-compound command) invokes a gated operation.
# Splits $1 on the shell separators && || ; | and newlines, strips leading
# whitespace plus wrapper words (`(`, `\`, `command `) and `VAR=value` env
# prefixes from each segment, and returns 0 if ANY segment STARTS with a gated
# `git …` invocation on a word boundary (matched by $TRIGGER_RE). Replaces
# literal-prefix `case` matching, which silently skipped the gate for
# `cd x && git commit`, `echo y; git push`, or a leading space (#88: NEVER skip
# the gate silently). Matching a segment START means a quoted `echo "git commit"`
# does NOT trigger it. Known limitation: it cannot see through `sh -c`, `eval`,
# or obfuscation — a seatbelt, not a sandbox.
is_scan_trigger() {
  # Pre-expanded newline: zsh does NOT expand $'\n' in the REPLACEMENT of
  # ${var//pat/repl} (it inserts the literal characters), so an inline $'\n'
  # left compound commands unsplit there and the gate silently skipped
  # `cd x && git commit` (#391). A plain variable expands identically in
  # bash and zsh. ($'\n' in PATTERN position expands fine in both.)
  local input="$1" segment nl=$'\n'
  # FIX B: join `\<newline>` continuations into a space FIRST, so a command
  # split across lines with a trailing backslash stays ONE logical segment
  # (otherwise the subcommand/flag lands in a segment not starting with git).
  input="${input//\\$'\n'/ }"
  input="${input//&&/$nl}"
  input="${input//||/$nl}"
  input="${input//;/$nl}"
  input="${input//|/$nl}"
  # `<<<` feeds the already-expanded value as data — no re-evaluation — so a
  # command that contains backticks/$() is inspected, never executed.
  while IFS= read -r segment; do
    segment="${segment#"${segment%%[![:space:]]*}"}"        # strip leading ws
    # FIX C: peel wrappers so `(git …`, `\git`, `command git …` and
    # `VAR=val git …` all reduce to a plain `git …` before matching.
    while [[ "$segment" == \(* ]]; do                       # strip leading ( runs
      segment="${segment#\(}"
      segment="${segment#"${segment%%[![:space:]]*}"}"
    done
    segment="${segment#\\}"                                 # strip a leading backslash (\git)
    while [[ "$segment" =~ ^[A-Za-z_][A-Za-z0-9_]*= ]]; do  # strip VAR=val prefixes
      case "$segment" in
        *[[:space:]]*)
          segment="${segment#*[[:space:]]}"
          segment="${segment#"${segment%%[![:space:]]*}"}"
          ;;
        *) segment=""; break ;;
      esac
    done
    if [[ "$segment" == command\ * ]]; then                 # strip a leading `command ` word
      segment="${segment#command }"
      segment="${segment#"${segment%%[![:space:]]*}"}"
    fi
    # FIX C: allow git global options between `git` and the subcommand
    # (`git -c k=v commit`, `git -C /repo push`). $TRIGGER_RE's trailing boundary
    # keeps `git commitgraph` / `git config …` from matching.
    if printf '%s' "$segment" | grep -qE "$TRIGGER_RE"; then
      return 0
    fi
  done <<< "$input"
  return 1
}

# Resolution of the working tree the commit acts on (#454). Shared body.
# Shared worktree resolver — inlined into each gate hook at render time (see the
# include directive in the source scripts + lib/hook-includes.ts). Requires the
# `extract-cmd` partial to have run first ($payload and $cmd in scope).
#
# WHY (#454): settings.json invokes these hooks as
# `bash "$CLAUDE_PROJECT_DIR/.claude/scripts/check-semgrep.sh"`, so the hook
# PROCESS starts in the MAIN repo even when the commit happens inside an agent
# worktree under `.claude/worktrees/`. The old `cd "$(git rev-parse
# --show-toplevel)"` therefore resolved the main repo — whose tree is clean — so
# `git diff --name-only main` returned 0 files and the gate exited 0. Not a false
# negative from the scanner: the scanner never ran. A `cd` to an arbitrary tree
# is exactly the bug, so nothing below ever guesses: every candidate must prove
# it is a git working tree, or the next one is tried — and the one the COMMAND
# names must additionally prove it is part of the repository being protected
# (see the same-repository constraint in `navori_worktree`).
#
# `navori_worktree` prints the absolute root of the working tree the gated git
# command will act on, or nothing when none resolves. It is a FUNCTION, not a
# top-level assignment, because `quality-gate-pre-commit` inlines this partial on
# a path that runs on EVERY Bash tool call: callers pay the git/jq probes only
# after their own trigger matched.

# First shell token of $1: a leading single/double-quoted string (so a path with
# spaces survives) or an unquoted run of non-space characters.
navori_first_token() {
  local s="$1"
  case "$s" in
    \"*) s="${s#\"}"; printf '%s' "${s%%\"*}" ;;
    \'*) s="${s#\'}"; printf '%s' "${s%%\'*}" ;;
    *) printf '%s' "${s%%[[:space:]]*}" ;;
  esac
}

# Directory named by the command itself, if any. Two shapes, both real in this
# harness: `git -C <dir> commit …` (git names its own tree) and
# `cd <dir> && git commit …` (how an agent commits into its worktree from a
# session anchored elsewhere). Prints the raw token; the caller resolves it.
#
# TODO(scope): only the FIRST segment is inspected for `cd`. A `cd` buried
# mid-chain (`pnpm build && cd sub && git commit`) falls through to the payload
# cwd, which is right whenever that `cd` stays inside the same repo. Walk the
# segments if a real command shows up where it does not.
navori_cmd_dir() {
  local text="$1" rest="" head=""
  case "$text" in
    *"git -C "*)
      rest="${text#*git -C }"
      ;;
    *)
      head="${text%%&&*}"
      head="${head#"${head%%[![:space:]]*}"}"
      case "$head" in
        "cd "*) rest="${head#cd }" ;;
      esac
      ;;
  esac
  [ -n "$rest" ] || return 1
  rest="${rest#"${rest%%[![:space:]]*}"}"
  # A token that needs the shell to expand it ($VAR, `sub`, ~, globs) is NOT
  # resolved here: guessing wrong points the scan at the wrong tree, which is
  # the very failure this partial exists to kill. Ignoring it just falls through
  # to the next candidate.
  case "$rest" in
    ""|*'$'*|*'`'*|*'*'*|*'?'*|"~"*) return 1 ;;
  esac
  navori_first_token "$rest"
}

# Absolute, symlink-resolved path of a working tree's SHARED git dir, or nothing
# when $1 is not inside a git working tree. `--git-common-dir` names the `.git`
# of the MAIN checkout, so every linked worktree of one repository — and every
# subdirectory of it — reports the SAME value, while a different repository
# reports its own and a submodule reports `<main>/.git/modules/<name>`. That
# makes it an identity test for "same repository", which `--show-toplevel` (one
# per working tree) and `--git-dir` (one per worktree) are not.
navori_repo_id() {
  local dir="$1" common=""
  common=$(git -C "$dir" rev-parse --git-common-dir 2>/dev/null) || return 1
  [ -n "$common" ] || return 1
  # `git -C <dir>` chdirs to <dir> first, so a relative answer (`.git`,
  # `../../.git`) is relative to <dir>. `pwd -P` canonicalises both sides the
  # same way, which also settles macOS's /var vs /private/var symlink.
  (cd "$dir" && cd "$common" && pwd -P) 2>/dev/null
}

# First argument that resolves to a git working tree; prints its root.
navori_first_tree() {
  local candidate toplevel
  for candidate in "$@"; do
    [ -n "$candidate" ] || continue
    [ -d "$candidate" ] || continue
    toplevel=$(git -C "$candidate" rev-parse --show-toplevel 2>/dev/null) || continue
    [ -n "$toplevel" ] || continue
    printf '%s' "$toplevel"
    return 0
  done
  return 1
}

# Resolution, most specific first:
#   1. the directory the command names (`git -C` / a leading `cd`), ONLY when it
#      belongs to the same repository as the anchor (see the constraint below);
#   2. the payload's `.cwd` — Claude Code sends the CURRENT working directory of
#      the tool call, a documented field distinct from $CLAUDE_PROJECT_DIR (the
#      project root). In an agent worktree these differ; that gap IS #454;
#   3. the hook process's own cwd — the pre-#454 behaviour, still correct for a
#      plain terminal or git-hook invocation.
navori_worktree() {
  local payload_cwd anchor named anchor_repo="" named_repo=""
  payload_cwd=$(payload_field cwd)
  # A relative `cd sub` resolves against the shell's cwd, which is the payload's
  # when Claude Code sends one and the hook process's otherwise.
  anchor="$payload_cwd"
  [ -d "$anchor" ] || anchor="$PWD"
  named=$(navori_cmd_dir "$cmd" || true)
  case "$named" in
    "") ;;
    /*) ;;
    *) named="$anchor/$named" ;;
  esac
  # SAME-REPOSITORY CONSTRAINT — DO NOT REMOVE (#454, review finding).
  # Candidate 1 is the only one the COMMAND controls, and it is tried first, so
  # accepting any git tree it happens to name lets that command OVERRIDE the
  # trustworthy candidates below it: `git -C <other-repo> log && git commit`,
  # `cd <other> && cd <wt> && git commit`, `cd <sub> && cd .. && git commit`, or
  # merely the bytes `git -C <path>` inside a commit MESSAGE, all aimed the scan
  # at a foreign tree with nothing to scan — exit 0 with the scanner never run,
  # which is the very failure #454 is about (and, for a commit in the main repo,
  # strictly worse than not resolving worktrees at all).
  # So a directory the command names is accepted only when it is part of the
  # repository the hook is protecting, i.e. the anchor's. Linked worktrees share
  # the main checkout's git dir, so every legitimate agent worktree passes; a
  # different repository and a submodule (its own git dir under
  # `<main>/.git/modules/`) do not, and fall through to the payload cwd — the
  # stricter direction. An unresolvable anchor drops candidate 1 for the same
  # reason: nothing to check it against.
  # Ceiling: two linked worktrees of the SAME repository are indistinguishable
  # this way, so naming a sibling worktree still beats the payload cwd. Both are
  # trees of the repo being protected, so the scan stays inside it. Walk the
  # segments to the one that actually carries the `git commit` if a real command
  # shows up where that is not enough.
  if [ -n "$named" ]; then
    anchor_repo=$(navori_repo_id "$anchor" || true)
    named_repo=$(navori_repo_id "$named" || true)
    if [ -z "$anchor_repo" ] || [ "$named_repo" != "$anchor_repo" ]; then
      named=""
    fi
  fi
  navori_first_tree "$named" "$payload_cwd" "$PWD" || true
}

# No command extracted (empty $cmd) → run unconditionally (defensive fallback). A
# real command that is NOT a scanned op → skip. Anything else → scan.
if [ -n "$cmd" ] && ! is_scan_trigger "$cmd"; then
  exit 0
fi

if ! command -v semgrep >/dev/null 2>&1; then
  echo "⊘ semgrep not installed locally — skip (install: brew install semgrep)" >&2
  exit 0
fi

# This script's own bytes feed the cache fingerprint below, so pin its path
# BEFORE the `cd` (a relative `$0` would stop resolving afterwards). Read at top
# level on purpose: inside a function zsh rebinds `$0` to the function name.
script_path="$0"
case "$script_path" in /*) ;; *) script_path="$PWD/$script_path" ;; esac

# Run from the tree the commit acts on — NOT from the hook process's cwd, which
# is the main repo even when the diff lives in an agent worktree (#454). Also
# keeps changed paths relative, so a repo path with spaces stays robust; the
# NUL-delimited read handles spaces in filenames, and the
# `-- '*.ts' '*.tsx'` pathspec filters by extension without a pipe.
tree=$(navori_worktree)
if [ -z "$tree" ]; then
  echo "⊘ semgrep: no git working tree resolved for this command — skip" >&2
  exit 0
fi
cd "$tree"

# branchBase is shell-quoted at render time via the shq: marker (#197/#249): a
# hostile branchBase in navori.config.json lands here as an inert literal, so it
# can only ever be a branch ref — never an injected command (this hook runs on
# every git commit/push via PreToolUse(Bash)).
base='main'

# Resolved to a SHA, not left as a ref: it is BOTH the scan's baseline and part
# of the cache fingerprint below, so it has to name one immutable commit.
base_sha=$(git rev-parse --verify --quiet "$base^{commit}" 2>/dev/null || true)
if [ -z "$base_sha" ]; then
  echo "⊘ branch '$base' does not exist in $tree — skip semgrep" >&2
  exit 0
fi
base_short=$(git rev-parse --short "$base_sha" 2>/dev/null || printf '%s' "$base_sha")

# `git diff` runs inside a process substitution, whose exit status the shell
# never reports, and its stderr used to go to /dev/null — so a diff that FAILED
# (exit 128: unborn HEAD, a corrupt index, a base that vanished mid-run)
# produced zero records and was indistinguishable from "nothing changed": the
# hook printed `0 files to scan` and exited 0 (#511). The sentinel carries the
# status back out of the subshell. It can never collide with a real record: the
# pathspec restricts the list to `*.ts`/`*.tsx`.
diff_sentinel='@navori-diff-status:'
diff_status=""
files=()
while IFS= read -r -d '' f; do
  case "$f" in
    "${diff_sentinel}"*) diff_status="${f#"${diff_sentinel}"}"; continue ;;
  esac
  files+=("$f")
done < <(
  # `|| diff_rc=$?` and not a bare `$?`: the subshell inherits `set -e`, which
  # would kill it on a failing `git diff` before the sentinel is ever written.
  diff_rc=0
  git diff --name-only -z --diff-filter=ACMRT "$base_sha" -- '*.ts' '*.tsx' || diff_rc=$?
  printf '%s%s\0' "$diff_sentinel" "$diff_rc"
)
if [ "$diff_status" != "0" ]; then
  echo "✗ semgrep: \`git diff\` FAILED (exit ${diff_status:-unknown}) in $tree — NOTHING was scanned" >&2
  echo "  this is not a security verdict: no file was compared against $base ($base_short)" >&2
  exit 1
fi

# An empty scan is NOT a silent green (#454): say which tree and which base
# produced it, so "there was nothing to scan" reads differently from "I scanned
# and found nothing". The two used to be indistinguishable, which is how a gate
# that never ran passed for a whole day.
if [ ${#files[@]} -eq 0 ]; then
  echo "⊘ semgrep: 0 files to scan — no *.ts/*.tsx differ from $base ($base_short) in $tree" >&2
  exit 0
fi

# --- Content cache (#402) ----------------------------------------------------
# The gate fires on commit AND push AND `gh pr create`, so one cycle used to
# rescan byte-identical content up to three times at ~4s each. The marker
# records the fingerprint of the last GREEN scan; an exact match skips the
# rescan. The fingerprint covers every input that can flip the verdict:
#
#   1. the scanned paths, in the order the scan receives them;
#   2. the exact bytes of each scanned file — `git hash-object --no-filters`
#      hashes the WORKING-TREE content semgrep reads (`--no-filters` skips
#      gitattributes clean/eol conversion, so the hash is the raw bytes);
#   3. `.semgrepignore`, which semgrep applies to its targets;
#   4. the semgrep binary's identity — path plus `ls -l` (size, mtime and, for
#      the usual symlinked install, the versioned target), so an upgrade in
#      place invalidates instead of inheriting the old ruleset's verdict;
#   5. this script's own bytes — the scan arguments (`--config=p/default`,
#      `--error`) are constants HERE, so a re-render that tightens the ruleset
#      must not inherit a marker earned under the looser one;
#   6. the baseline commit the scan compares against (#454). The verdict is
#      "findings NOT already at $base_sha", so the same bytes legitimately flip
#      from green to red (or back) when the base branch moves.
#
# Untracked files are absent from both the fingerprint and the scan: the file
# list comes from `git diff`, so an untracked file is never scanned and can
# never be masked by a hit. Anything the cache cannot establish (no git dir, no
# `date`, a failing hash) leaves $cache_key empty → full scan. The marker is
# published only if the fingerprint still matches AFTER the scan, so it can
# never attest to bytes semgrep did not read. The cache may turn a green into a
# skip, NEVER an unscanned change into a green.
#
# Marker lifetime, in seconds. The fingerprint pins the scanned bytes and the
# semgrep binary, but NOT the registry rules behind `p/default`, which semgrep
# refetches on its own schedule. The TTL bounds how long a stale ruleset can be
# masked; one hour still covers a full commit → push → PR cycle (minutes). A
# fixed assignment, not `${CACHE_TTL:-3600}`: a gate must not let the
# environment it runs in extend how long its own verdict stays valid.
CACHE_TTL=3600

git_dir=$(git rev-parse --absolute-git-dir 2>/dev/null || true)
now=$(date +%s 2>/dev/null || true)
case "$now" in ''|*[!0-9]*) now="" ;; esac

# A function because the recipe runs TWICE: once before the scan to look the
# marker up, once after it to prove nothing moved underneath (see the write
# below). Writes the fingerprint to stdout; fails if any ingredient is missing.
#
# `|| exit 1` on each hash: the caller tests this function's status with `||`,
# which suppresses errexit inside it, so a failing hash would otherwise just
# drop its line and yield a fingerprint over an incomplete recipe. The braces
# are a pipeline element, hence their own subshell — the exit is local to it and
# collapses the whole key to empty (→ full scan).
semgrep_fingerprint() {
  {
    printf '%s\n' "$semgrep_bin"
    printf '%s\n' "$base_sha"
    ls -ldn "$semgrep_bin" 2>/dev/null || true
    git hash-object --no-filters -- "$script_path" || exit 1
    if [ -f .semgrepignore ]; then
      git hash-object --no-filters -- .semgrepignore || exit 1
    fi
    printf '%s\n' "${files[@]}"
    git hash-object --no-filters -- "${files[@]}" || exit 1
  } | git hash-object --stdin
}

cache_key=""
marker=""
if [ -n "$git_dir" ] && [ -d "$git_dir" ] && [ -n "$now" ]; then
  semgrep_bin=$(command -v semgrep)
  cache_key=$(semgrep_fingerprint) || cache_key=""
  # Per-worktree git dir on purpose: a worktree's `.git` is a FILE, and two
  # worktrees hold different content, so they must not share a marker.
  marker="$git_dir/navori-semgrep-ok"
fi

if [ -n "$cache_key" ] && [ -f "$marker" ]; then
  cached_key=""
  cached_ts=""
  # A truncated or hand-edited marker can only ever MISS: the comparison is on
  # the whole key, and a non-numeric timestamp collapses to 0 (never fresh).
  read -r cached_key cached_ts < "$marker" || true
  case "$cached_ts" in ''|*[!0-9]*) cached_ts=0 ;; esac
  age=$(( now - cached_ts ))
  # A marker from the future (clock skew, restored backup) is not trusted.
  if [ "$cached_key" = "$cache_key" ] && [ "$cached_ts" -gt 0 ] && [ "$age" -ge 0 ] &&
    [ "$age" -lt "$CACHE_TTL" ]; then
    echo "✓ semgrep: diff unchanged since last green scan — skip" >&2
    exit 0
  fi
fi

echo "▶ semgrep: ${#files[@]} changed file(s) vs $base ($base_short) in $tree" >&2

# `--baseline-commit` makes the gate fail on findings this branch INTRODUCES,
# not on debt it inherited (#454). Without it, fixing the worktree resolution
# above would have turned a decorative gate into one that blocks any commit
# touching a file with pre-existing hits — e.g. the 7 findings already in `main`
# under packages/cli/src/lib/marker.ts. semgrep runs the baseline scan in a git
# worktree it creates from that commit, so it needs neither a clean tree nor an
# ancestor relationship (verified on 1.174.0 with unstaged/staged/untracked
# changes, from a linked worktree, and with a diverged base). The cost is a
# second scan pass; the content cache above absorbs the repeats within a cycle.
echo "  baseline: findings already at $base ($base_short) are not blocking" >&2

# `>&2` is not cosmetic (#510): a PreToolUse hook shows the user its stderr and
# swallows its stdout, so the findings themselves — the whole point of the gate
# — used to be written where nobody could read them, leaving only the `▶ …`
# progress line visible.
scan_status=0
semgrep scan \
  --config=p/default \
  --error \
  --metrics=off \
  --baseline-commit "$base_sha" \
  "${files[@]}" >&2 || scan_status=$?

# `--error` maps findings to exit 1; anything above that is semgrep itself
# failing (invalid ruleset, unusable baseline, crash). Say WHY, so a broken
# scanner is never read as a security verdict — and see the exit mapping at the
# bottom, which is where that distinction becomes a decision.
if [ "$scan_status" -gt 1 ]; then
  echo "✗ semgrep: scan FAILED with exit $scan_status (not a findings verdict) — nothing was validated" >&2
elif [ "$scan_status" -eq 1 ]; then
  echo "✗ semgrep: new findings vs $base ($base_short) — BLOCKED" >&2
else
  echo "✓ semgrep: ${#files[@]} file(s) scanned vs $base ($base_short) — no new findings" >&2
fi

# Only a GREEN scan writes the marker: a red one (or a crashed/interrupted run)
# leaves nothing behind, so the retry rescans the same content.
#
# And only a scan whose input never moved: $cache_key was taken BEFORE the scan,
# so a writer racing that window (format-on-save, a watch build, a second agent
# in the same worktree) would have semgrep read content B while the marker
# claims content A — leaving A green without ever being scanned, for a whole
# TTL. Re-taking the fingerprint over the now-warm files costs milliseconds and
# keeps the marker describing exactly the bytes semgrep read.
if [ "$scan_status" -eq 0 ] && [ -n "$cache_key" ]; then
  post_key=$(semgrep_fingerprint) || post_key=""
  if [ "$post_key" = "$cache_key" ]; then
    # stderr silenced on the OUTER group: redirections apply left to right, so
    # `> "$marker" 2>/dev/null` would report its own failure (read-only .git, a
    # marker path that is a directory) on the still-unredirected stderr — which
    # a PreToolUse hook shows to the user. Failing to cache is not an error.
    { printf '%s %s\n' "$cache_key" "$now" > "$marker"; } 2>/dev/null || true
  fi
fi

# PreToolUse EXIT CONTRACT (#510). Claude Code blocks a tool call ONLY on exit
# 2; every other non-zero code is shown to the user and the call PROCEEDS. The
# old `exit "$scan_status"` handed semgrep's own code straight through, and
# `--error` maps findings to 1 — so this gate printed a progress line, listed
# its findings where nobody saw them, and blocked exactly nothing. The two
# outcomes the block above already tells apart become two different decisions:
#
#   findings (1)        → 2. A security VERDICT about this diff: block.
#   scanner broken (>1) → 1. NOT a verdict — nothing was validated, so it is
#                         reported loudly and the call proceeds. Blocking on a
#                         tooling failure would spend the gate's credibility on
#                         a claim it cannot make.
#   clean (0)           → 0.
case "$scan_status" in
  0) exit 0 ;;
  1) exit 2 ;;
  *) exit 1 ;;
esac
